fn trunc_len(n: usize, m: usize) -> usize {
    // If the input length n is greater than m, we truncate by m;
    // otherwise we must return at least length 1.
    if n > m {
        n - m
    } else {
        1
    }
}

fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    // Compute how many elements to keep
    let keep = trunc_len(c.len(), m as usize);
    // Take that many from the front, preserving order
    c.into_iter().take(keep).collect()
}

