    #[test]
    fn test_legder() {
        let v = vec![1.0, 2.0, 3.0, 4.0];

        // m = 0 → unchanged
        assert_eq!(legder(v.clone(), 0, 42.0), vec![1.0, 2.0, 3.0, 4.0]);

        // m = 2 → drop last 2 → keep first 2
        assert_eq!(legder(v.clone(), 2, 0.0), vec![1.0, 2.0]);

        // m = len → keep first only
        assert_eq!(legder(v.clone(), 4, 1.23), vec![1.0]);

        // m > len → keep first only
        assert_eq!(legder(v.clone(), 10, -5.0), vec![1.0]);
    }
